contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= sendAmount);
        // record pre-state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // make a plain call to withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // General rule: either the call succeeded and cleared the contract balance to zero leaving depositsCount unchanged,
        // or it reverted and both balance and depositsCount are unchanged.
        assert((!reverted && afterBalance == 0 && afterDeposits == beforeDeposits) || (reverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits));
    }
    receive() external payable {}
}

